/bin/zsh -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Update File: TopModule.sv
@@
 parameter idle=4'd0,
 		  s1_d0=4'd1,
           s2_d01=4'd2,
           s3_d011=4'd3,
-          s4_d0110=4'd2;
+          s4_d0110=4'd4;
@@
 always @(pstate or rst_n)
 begin
-    if("'!rst_n==1)
+    if(!rst_n)
         match=1'"'b0;
     else if(pstate==s4_d0110)						//Entering state s4_d0110 means all four bits matched, assert match signal high
             match=1'b1;
*** End Patch
PATCH

cat > tb.sv <<'TB'
"'`timescale 1ns/1ps
module tb;
  reg clk = 0;
  reg rst_n = 0;
  reg data = 0;
  reg data_valid = 0;
  wire match;

  TopModule dut(.clk(clk), .rst_n(rst_n), .data(data), .data_valid(data_valid), .match(match));

  always #5 clk = ~clk;

  task send_bit(input reg bitval, input reg valid);
    begin
      data = bitval;
      data_valid = valid;
      @(posedge clk);
      #1;
      $display("t=%0t valid=%0b data=%0b match=%0b state=%0d", $time, data_valid, data, match, dut.pstate);
    end
  endtask

  initial begin
    repeat (2) @(posedge clk);
    rst_n = 1;
    #1;

    // Should not match on partial sequence 01
    send_bit(0,1);
    send_bit(1,1);

    // Invalid cycle should be ignored; 0 1 x 1 0 => match once
    send_bit(0,1);
    send_bit(1,1);
    send_bit(0,0);
    send_bit(1,1);
    send_bit(0,1);

    // Overlap check: 0 1 1 0 => match once
    send_bit(0,1);
    send_bit(1,1);
    send_bit(1,1);
    send_bit(0,1);

    $finish;
  end
endmodule
TB

iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

